// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Initialize a data source.
	// (POST /ginfra/datasource/init)
	GiControlDatasourceInit(ctx context.Context, request GiControlDatasourceInitRequestObject) (GiControlDatasourceInitResponseObject, error)
	// Reset the service/server.
	// (POST /ginfra/manage/reset)
	GiControlManageReset(ctx context.Context, request GiControlManageResetRequestObject) (GiControlManageResetResponseObject, error)
	// Stop the service/server.
	// (POST /ginfra/manage/stop)
	GiControlManageStop(ctx context.Context, request GiControlManageStopRequestObject) (GiControlManageStopResponseObject, error)
	// Get specifics for this service
	// (GET /ginfra/specifics)
	GiGetSpecifics(ctx context.Context, request GiGetSpecificsRequestObject) (GiGetSpecificsResponseObject, error)
	// Get log for a test.
	// (GET /gitest/log)
	GiTestLog(ctx context.Context, request GiTestLogRequestObject) (GiTestLogResponseObject, error)
	// Remove a list of completed tests.
	// (POST /gitest/remove)
	GiTestRemove(ctx context.Context, request GiTestRemoveRequestObject) (GiTestRemoveResponseObject, error)
	// Run a test.
	// (POST /gitest/run)
	GiTestRun(ctx context.Context, request GiTestRunRequestObject) (GiTestRunResponseObject, error)
	// Get status for all tests.
	// (GET /gitest/status/all)
	GiTestStatusAll(ctx context.Context, request GiTestStatusAllRequestObject) (GiTestStatusAllResponseObject, error)
	// Get status for a test.
	// (GET /gitest/status/test)
	GiTestStatusTest(ctx context.Context, request GiTestStatusTestRequestObject) (GiTestStatusTestResponseObject, error)
	// Stop a test.
	// (GET /gitest/stop)
	GiTestStop(ctx context.Context, request GiTestStopRequestObject) (GiTestStopResponseObject, error)
}

